/// <summary>
///     AVA <c>modified</c> method.
///     AVA - Schneider 06.06.2024
/// </summary>
public void modified()
{
    FormDataSource  locSalesTableDs;
    SalesTable      locSalesTable;

    locSalesTableDs = element.SalesTable_DS;
    locSalesTable   = locSalesTableDs.cursor();

    next modified();

    if(locSalesTable.RecId)
    {
        locSalesTable.avaCheckPickUpFeeChange(true);
        locSalesTableDs.refresh();
    }
}
